      pain: H.line(44, 46, 54, 42, 2.5) + H.line(66, 42, 76, 46, 2.5),
      angry: H.line(44, 42, 54, 47, 3) + H.line(66, 47, 76, 42, 3),
      skeptical: H.line(44, 45, 54, 45, 2.5) + H.line(66, 43, 76, 40, 2.5),
      surprised: H.path("M44,43 q5,-4 10,0", "none", 2.5) + H.path("M66,43 q5,-4 10,0", "none", 2.5),
